import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-preparacion-del-corazon', 'C',
 [dict(t=233, e=305, titulo='Ocuparnos de la salvación', txt='He estado intentando esforzarme, por lo menos yo y tal vez algunos otros hermanos juntamente conmigo, en ocuparnos, como dice este verso de Filipenses: agarrar una ocupación nueva. Y dice: «Amados míos, tal como siempre os habéis obedecido, no solo en mi presencia, sino ahora mucho más en mi ausencia, ocupaos de vuestra salvación con temor y con temblor». La ocupación de la salvación, y el ángulo en el cual he estado enfocándome más, es el que está relacionado con esta cita de Hechos 2:40, que dice: «Sed salvos de esta generación perversa». Entonces hay que ocuparse de la salvación por un lado y, por el otro, ser salvo de la generación perversa. Y eso da a entender que, si tenemos la expectativa de salir de la tierra, tenemos que salir de la generación; es decir, no nos podemos parecer a la generación que nos rodea.'),
  dict(t=2106, e=2184, titulo='Un camino parejo es un camino de paz', txt='El hermano que está a la par suya, si ya está siendo emparejado, vive en paz. Pregúntele al hermano que está a la par suya: ¿tú vives en paz o vives peleando? Porque el camino que ya está parejo es un camino de paz. Si ya estamos siendo emparejados, somos un camino de santidad. […] Si ya somos un camino parejo, somos un camino de justicia: «Del camino de la justicia está la vida». Si ya somos un camino parejo, somos un camino de vida: «Me mostrarás la senda de la vida». Si ya somos un camino parejo, somos un camino eterno: «Guíame en el camino eterno». […] «Preguntad por las sendas antiguas y hallaréis descanso para vuestra alma». Si somos un camino parejo, pues somos rectos: «Enderezad el camino a Jehová», que fue el verso que leímos. Si estamos transitando por el camino correcto, somos un camino angosto que lleva a la vida. Somos un camino de sabiduría, somos un camino de verdad. Somos un camino de los justos. Somos la senda antigua. Somos el camino perfecto. Somos el camino del entendimiento. Somos el camino de Dios.'),
  dict(t=3228, e=3276, titulo='No puede haber iniquidad con servicio', txt='Entonces, hermano, este es un llamado a santidad, que es, fíjese, lo que menos hay ahora, no solo en la iglesia, sino en todo el mundo: un llamado, hermano, a reflexionar qué hablamos, qué pensamos, qué hacemos, qué es lo que deseamos. Es eso lo que está haciendo la corrección de Isaías. Y yo creo que sí deja muy bien marcada la idea de que, hermano, no puede haber iniquidad con servicio: no cuadra. Al Señor no le agrada así.')],
 [dict(t=1741, txt='¿Cuál es la administración del corazón? Aprender humildad y mansedumbre: manso con los de arriba, humilde con los de abajo.'),
  dict(t=2480, txt='¿Será que la manera en que yo busco a Dios, la manera en que yo sirvo a Dios, es la manera a la que Dios le agrada, o solamente lo hago por religión? Tengo que verificar.'),
  dict(t=3653, txt='Solamente está esperando el Señor que hoy le digamos: «Te entrego mis caminos. Endereza mi camino, Señor, porque no he estado caminando bien».')],
 ['Ocuparse de la salvación es agarrar una ocupación nueva: ¿en qué te vas a ocupar esta semana para parecerte menos a la generación que te rodea?',
  'Donde está tu tesoro, ahí está tu corazón. ¿A qué le das prioridad hoy, y qué le estás dando al Señor: tus obras o tu corazón?',
  '¿Tu manera de buscar y servir a Dios le agrada a Él, o la haces solo por religión? ¿Qué revisarías hoy, como quien consulta el mapa en un viaje largo?'],
 inicio=102)
